function validate(input) {
  const [{ Flights = [] }] = input;
  const routes = new Set();
  for (const [from, to, count] of Flights) {
    if (from === null || to === null || count === null) return 'Flights rows may not contain null.';
    if (from === to) return `Airport ${from} cannot have a route to itself.`;
    const key = `${from}>${to}`;
    if (routes.has(key)) return `The route ${from} -> ${to} appears twice.`;
    if (count < 1) return 'flights_count must be at least 1.';
    routes.add(key);
  }
  return null;
}

