function generate(rand, size) {
  const small = size === 'small';
  const airports = small ? 5 : 200;
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const seen = new Set(), Flights = [];
  for (let tries = 0; Flights.length < rows && tries < rows * 20; tries++) {
    const from = 1 + Math.floor(rand() * airports), to = 1 + Math.floor(rand() * airports);
    if (from === to || seen.has(`${from}>${to}`)) continue;
    seen.add(`${from}>${to}`);
    // Small counts make equal totals, and so ties, common.
    Flights.push([from, to, 1 + Math.floor(rand() * (small ? 6 : 100))]);
  }
  return [{ Flights }];
}
